import numpy as np
def equation(t, P, params):
    a,b,c,d,e,f,g,h,k,m = params
    L = np.log(P)
    return a/P + b + c*P + d*P**2 + e*P*L + f*P*L**2 + t*(g + h*P + k*P**2 + m*P*L)
